// Builds the Graph API template message from payload.wa (the same values the portal and email show). No lead names, no newlines in parameters.
const CLEAN = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, 1000);
const out = [];
for (const it of $input.all()) {
  const j = it.json; const p = j.payload || {}; const wa = p.wa || {};
  const wk = String(p.week || '').toLowerCase().replace('-', '');            // "2026-W41" -> "2026w41"
  const rp = 'rp_' + wk;
  let name, keys, buttons;
  if (p.edition === 'midcycle') { name = 'broker_midcycle'; keys = ['v1','v2','v3','v4','v5','v6','v7','v8']; buttons = ['r/' + rp]; }
  else if (p.edition === 'cycle_end') { name = 'broker_cycle_end'; keys = ['v1','v2','v3','v4','v5','v6','v7']; buttons = ['renew/' + j.cycle_id, 'r/' + rp]; }
  else if (p.s7_ask) { name = 'broker_weekly'; keys = ['v1','v2','v3','v4','v5','v6']; buttons = [String(p.s7_ask.deep_link || ('ask/' + rp)), 'r/' + rp]; }
  else { name = 'broker_weekly_noask'; keys = ['v1','v2','v3','v4','v5']; buttons = ['r/' + rp]; }
  const params = keys.map((k) => { if (wa[k] == null) throw new Error('payload.wa.' + k + ' missing for ' + name); return { type: 'text', text: CLEAN(wa[k]) }; });
  const components = [{ type: 'body', parameters: params }].concat(buttons.map((b, i) => ({ type: 'button', sub_type: 'url', index: String(i), parameters: [{ type: 'text', text: b }] })));
  out.push({ json: { report_id: j.report_id, template: name, to: j.wa_to,
    payload: { messaging_product: 'whatsapp', to: j.wa_to, type: 'template', template: { name, language: { code: 'en' }, components } } } });
}
return out;

// Pair each Graph response with its report (same order as the Build WhatsApp template items).
const built = $('Build WhatsApp template').all();
return $input.all().map((it, i) => ({ json: { report_id: built[i].json.report_id, ok: it.json.statusCode >= 200 && it.json.statusCode < 300,
  wa_message_id: (it.json.body && it.json.body.messages && it.json.body.messages[0] && it.json.body.messages[0].id) || null,
  error: it.json.statusCode >= 300 ? JSON.stringify(it.json.body || {}).slice(0, 300) : null } }));

