with u as (
  update public.report_history set status = 'sent', sent_wa_at = now(), updated_at = now() where id = $1::uuid and sent_wa_at is null
  returning id, broker_id
)
insert into ops.notifications (kind, recipient, channel, dedupe_key, payload, source)
select 'action', u.broker_id::text, 'email', 'broker-report-email-' || u.id, jsonb_build_object('report_id', u.id, 'template', 'broker_report_email', 'builder', 'scripts/build-broker-report-email.mjs', 'from', 'howzit@leadvelocity.co.za', 'bcc', 'howzit@leadvelocity.co.za', 'pdf', 'initials_only'), 'W14'
from u where not exists (select 1 from ops.notifications where dedupe_key = 'broker-report-email-' || u.id)
returning id;

with u as (
  update public.report_history set status = 'failed', updated_at = now() where id = $1::uuid and sent_wa_at is null returning id
)
insert into ops.notifications (kind, recipient, channel, dedupe_key, payload, severity, what, first_action)
select 'action', 'jonathan', 'console', 'w14-send-failed-' || u.id, jsonb_build_object('report_id', u.id, 'error', $2), 'amber',
       'A broker report did not send on WhatsApp', 'Check the WhatsApp number health tile, then re-send the report from the console'
from u where not exists (select 1 from ops.notifications where dedupe_key = 'w14-send-failed-' || u.id)
returning id;

