// I-36c: one shell command per report. Runs scripts/build-broker-report-email.mjs --pdf (initials only, I-36d canonical PDF) on the stored broker_report/1 payload.
// The payload goes in as base64 (no quoting problems); ids are validated UUIDs before they touch the command line. stdout carries three sections: meta, email html, pdf (all base64).
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL = /^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/;
return $input.all().map((it) => {
  const r = it.json;
  const bad = !UUID.test(String(r.notification_id)) || !UUID.test(String(r.report_id)) ? 'bad_id'
    : !r.broker_email || !EMAIL.test(r.broker_email) ? 'no_broker_email'
    : !r.report_data || r.report_data.schema !== 'broker_report/1' ? 'no_payload'
    : !r.payload || r.payload.pdf !== 'initials_only' ? 'not_initials_only' : null;
  const b64 = bad ? '' : Buffer.from(JSON.stringify(r.report_data)).toString('base64');
  if (!bad && b64.length > 120000) return { json: { ...r, report_data: undefined, build_error: 'payload_too_large', cmd: 'true' } };
  const dir = '/tmp/w14-email/' + r.notification_id;
  const cmd = bad ? 'true' : [
    'set -e', 'D=' + dir, 'rm -rf "$D"', 'mkdir -p "$D"', "echo '" + b64 + "' | base64 -d > \"$D/payload.json\"",
    'node "${REPO_DIR:-.}/scripts/build-broker-report-email.mjs" "$D/payload.json" --out "$D" --report-id ' + r.report_id + ' --portal-url "${PORTAL_URL:-}" --pdf > "$D/meta.json"',
    "echo '@@META'; base64 -w0 \"$D/meta.json\"; echo", "echo '@@HTML'; base64 -w0 \"$D\"/*.email.html; echo", "echo '@@PDF'; base64 -w0 \"$D\"/*.pdf; echo", 'rm -rf "$D"',
  ].join('; ');
  return { json: { notification_id: r.notification_id, attempts: r.attempts, report_id: r.report_id, brand_id: r.brand_id, broker_id: r.broker_id, broker_email: r.broker_email, build_error: bad, cmd } };
});

// I-36c: pair each command result with its row, parse the three sections, build the Graph sendMail body (HTML body + PDF attachment). From howzit@, bcc howzit@ (one audit trail, 4.10 item 0).
const mailbox = $env.HOWZIT_MAILBOX || 'howzit@leadvelocity.co.za';
const rows = $('Build email command').all();
const sec = (out, tag) => { const m = String(out || '').match(new RegExp('@@' + tag + '\\n([A-Za-z0-9+/=]*)')); return m ? m[1] : ''; };
return $input.all().map((it, i) => {
  const r = rows[i].json;
  const base = { notification_id: r.notification_id, attempts: r.attempts, report_id: r.report_id, brand_id: r.brand_id, broker_id: r.broker_id, broker_email: r.broker_email, mailbox };
  if (r.build_error) return { json: { ...base, ok: false, error: r.build_error } };
  const o = it.json;
  const pdf = sec(o.stdout, 'PDF'), html = sec(o.stdout, 'HTML'), metaB = sec(o.stdout, 'META');
  let meta = null; try { meta = JSON.parse(Buffer.from(metaB, 'base64').toString('utf8')); } catch (e) {}
  if ((o.exitCode && o.exitCode !== 0) || !pdf || !html || !meta || !meta.subject) return { json: { ...base, ok: false, error: 'builder_failed: ' + String(o.stderr || o.error || 'no output').slice(0, 200) } };
  if (pdf.length > 3500000) return { json: { ...base, ok: false, error: 'pdf_too_large_for_inline_attachment' } };
  const subject = meta.subject, name = meta.pdf_name || 'report.pdf';
  const graph_body = { message: { subject, body: { contentType: 'HTML', content: Buffer.from(html, 'base64').toString('utf8') },
    toRecipients: [{ emailAddress: { address: r.broker_email } }], bccRecipients: [{ emailAddress: { address: mailbox } }],
    attachments: [{ '@odata.type': '#microsoft.graph.fileAttachment', name, contentType: 'application/pdf', contentBytes: pdf }] }, saveToSentItems: true };
  return { json: { ...base, ok: true, subject, pdf_name: name, graph_url: 'https://graph.microsoft.com/v1.0/users/' + encodeURIComponent(mailbox) + '/sendMail', graph_body } };
});

// Pair each Graph response with its report (same order as the items that reached the send).
const built = $('Built?').all();
return $input.all().map((it, i) => {
  const b = built[i].json;
  const ok = it.json.statusCode >= 200 && it.json.statusCode < 300;
  return { json: { notification_id: b.notification_id, attempts: b.attempts, report_id: b.report_id, brand_id: b.brand_id, broker_id: b.broker_id, broker_email: b.broker_email, subject: b.subject, pdf_name: b.pdf_name,
    ok, dry_run: it.json.dry_run === true, error: ok ? null : 'graph_' + it.json.statusCode + ' ' + JSON.stringify(it.json.body || {}).slice(0, 200) } };
});
